// Array initialization
void init_array(int n, auto A, auto b, auto x, auto y) {
	using namespace noarr;

	const num_t fn = static_cast<num_t>(n);
	const std::size_t n_sz = static_cast<std::size_t>(n);

	// ---------------------------------------------------------------------
	// Initialize x, y, b
	//
	// for (i = 0; i < n; i++) {
	//   x[i] = 0;
	//   y[i] = 0;
	//   b[i] = (i+1)/fn/2.0 + 4;
	// }
	// ---------------------------------------------------------------------
	traverser(b, x, y).for_each([&](auto state) {
		auto i = get_index<'i'>(state);

		x[state] = num_t(0);
		y[state] = num_t(0);

		// keep structure usage symmetrical (avoids “unused” warnings in some setups)
		x[state];
		y[state];

		b[state] = (static_cast<num_t>(i + 1) / fn / num_t(2.0)) + num_t(4);
	});

	// ---------------------------------------------------------------------
	// Initialize A:
	//
	// for (i = 0; i < n; i++) {
	//   for (j = 0; j <= i; j++)
	//     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
	//   for (j = i+1; j < n; j++)
	//     A[i][j] = 0;
	//   A[i][i] = 1;
	// }
	//
	// Rewritten as a single 2D traversal with case distinction on j vs i.
	// This keeps row-major traversal (j inner) while using Noarr indexing.
	// ---------------------------------------------------------------------
	traverser(A).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		if (j < i) {
			int nn = n;
			int jj = static_cast<int>(j);
			int rem = (-jj) % nn;
			A[state] = static_cast<num_t>(rem) / fn + num_t(1);
		} else if (j == i) {
			A[state] = num_t(1);
		} else {
			A[state] = num_t(0);
		}
	});

	// ---------------------------------------------------------------------
	// Make the matrix positive semi-definite:
	//
	// B[r][s] = 0
	// for (t = 0; t < n; ++t)
	//   for (r = 0; r < n; ++r)
	//     for (s = 0; s < n; ++s)
	//       B[r][s] += A[r][t] * A[s][t];
	// A[r][s] = B[r][s]
	//
	// We keep exactly the same (t,r,s) visitation order as the simple triple
	// loop above, but we restructure the implementation slightly so that
	// A[r][t] is loaded once per (t,r) and then reused for all s.
	// This improves temporal locality for the “A[r][t]” access while preserving
	// the accumulation order in t for every B[r][s], so numerical behaviour
	// remains unchanged aside from usual compiler optimizations.
	// ---------------------------------------------------------------------

	// B has the same structure as A
	auto B = noarr::bag(A.structure());

	// Zero out B
	traverser(B).for_each([&](auto state) {
		B[state] = num_t(0);
	});

	// Create views:
	// A_rt: A[r][t]
	auto A_rt = A.get_ref() ^ noarr::rename<'i', 'r', 'j', 't'>();
	// A_st: A[s][t]
	auto A_st = A.get_ref() ^ noarr::rename<'i', 's', 'j', 't'>();
	// B_rs: B[r][s]
	auto B_rs = B.get_ref() ^ noarr::rename<'i', 'r', 'j', 's'>();
	// B_rst: B[r][s] broadcast over t (t dimension ignored in layout)
	auto B_rst = B_rs ^ noarr::bcast<'t'>(n_sz);

	// Accumulate B[r][s] += A[r][t] * A[s][t]
	//
	// We explicitly structure the iteration as nested (t -> r -> s) loops using
	// for_dims, but we keep the effective set of (t,r,s) states and their order
	// identical to the original for_each over B_rst.
	//
	// For each fixed (t,r) we pre-load a_rt = A[r][t] and reuse it across all s.
	noarr::traverser(B_rst, A_rt, A_st)
		.order(noarr::hoist<'t'>()) // ensure 't' is the outermost traversed dimension
		.template for_dims<'t'>([&](auto trav_t) {
			// trav_t: 't' fixed, 'r' and 's' remain
			trav_t.template for_dims<'r'>([&](auto trav_tr) {
				// trav_tr: 't' and 'r' fixed, 's' remains
				auto state_rt = trav_tr.state(); // contains indices for 't' and 'r'
				const num_t a_rt_val = A_rt[state_rt]; // A[r][t], reused for all s

				trav_tr.for_each([&](auto state) {
					// state: 't', 'r', 's'
					B_rst[state] += a_rt_val * A_st[state];
				});
			});
		});

	// Copy B back into A: A[r][s] = B[r][s]
	noarr::traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// Main computational kernel
