void kernel_ludcmp(auto A, auto b, auto x, auto y) {
	using namespace noarr;

	// Work on reference bags to make sure we always have a copyable,
	// non-owning view suitable for ^-based views (fix, rename, etc.).
	auto A_ref = A.get_ref();
	auto b_ref = b.get_ref();
	auto x_ref = x.get_ref();
	auto y_ref = y.get_ref();

	// Length in the 'i' dimension
	const std::size_t n = A_ref | get_length<'i'>();

	// ---------------------------------------------------------------------
	// LU factorization (Doolittle-like scheme)
	//
	// Original scalar pseudocode:
	// for (i = 0; i < N; i++) {
	//   for (j = 0; j < i; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < j; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w / A[j][j];
	//   }
	//   for (j = i; j < N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
	// }
	//
	// Using a single j-loop:
	//   max_k = (j < i ? j : i);
	//   w = A[i][j] - sum_{k=0..max_k-1} A[i][k]*A[k][j];
	//   if (j < i) A[i][j] = w / A[j][j];
	//   else       A[i][j] = w;
	//
	// Here we keep the same scalar algorithm, but:
	//  - traverse rows (dimension 'i') with for_dims<'i'>
	//  - create a row view A_row_i for the current i to make A[i][*]
	//    accesses contiguous
	//  - create a column view A_col_j for each j to make A[*][j]
	//    accesses contiguous
	//  - implement the k-loop as a simple scalar loop
	// ---------------------------------------------------------------------
	traverser(A_ref).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, 'j' remaining
		auto s_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(s_i);

		// 1D view of row i: dimension 'j' only
		auto A_row_i = A_ref ^ noarr::fix<'i'>(i_idx);

		// Traverse all columns j in row i
		trav_i.for_each([&](auto state) {
			const std::size_t j_idx = get_index<'j'>(state);

			// 1D view of column j: dimension 'i' only
			auto A_col_j = A_ref ^ noarr::fix<'j'>(j_idx);

			// Start from the original A[i][j]
			num_t w = A_row_i[noarr::idx<'j'>(j_idx)];

			// Upper bound of inner product; depends on the triangular
			// region we are in (L below diag, U on/above diag)
			const std::size_t max_k = (j_idx < i_idx) ? j_idx : i_idx;

			for (std::size_t k = 0; k < max_k; ++k) {
				// A[i][k] is contiguous in A_row_i,
				// A[k][j] is contiguous in A_col_j.
				w -= A_row_i[noarr::idx<'j'>(k)] *
				     A_col_j[noarr::idx<'i'>(k)];
			}

			if (j_idx < i_idx) {
				// Strictly lower triangular part (L):
				// divide by U[j][j].
				const num_t diag = A_col_j[noarr::idx<'i'>(j_idx)]; // A[j][j]
				A_row_i[noarr::idx<'j'>(j_idx)] = w / diag;
			} else {
				// Upper triangular part (U): store w directly.
				A_row_i[noarr::idx<'j'>(j_idx)] = w;
			}
		});
	});

	// ---------------------------------------------------------------------
	// Forward substitution: solve Ly = b
	//
	// for (i = 0; i < N; i++) {
	//   w = b[i];
	//   for (j = 0; j < i; j++)
	//     w -= A[i][j] * y[j];
	//   y[i] = w;
	// }
	//
	// We again traverse rows with for_dims<'i'> and use a row view A_row_i
	// for contiguous A[i][*] access; the j-loop is realized via a traverser
	// over the remaining 'j' dimension and a simple conditional j < i.
	// ---------------------------------------------------------------------
	traverser(y_ref, b_ref, A_ref).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(s_i);

		// Row view of A at i
		auto A_row_i = A_ref ^ noarr::fix<'i'>(i_idx);

		num_t w = b_ref[s_i];

		trav_i.for_each([&](auto state) {
			const std::size_t j_idx = get_index<'j'>(state);
			if (j_idx < i_idx) {
				w -= A_row_i[noarr::idx<'j'>(j_idx)] *
				     y_ref[noarr::idx<'i'>(j_idx)];
			}
		});

		y_ref[s_i] = w;
	});

	// ---------------------------------------------------------------------
	// Backward substitution: solve Ux = y
	//
	// for (i = N-1; i >= 0; i--) {
	//   w = y[i];
	//   for (j = i+1; j < N; j++)
	//     w -= A[i][j] * x[j];
	//   x[i] = w / A[i][i];
	// }
	//
	// We keep an ascending traversal over an "inverse" index:
	//   inv = 0..N-1, i = N-1-inv
	//
	// For each i we:
	//   - create a row view A_row_i (contiguous in j)
	//   - traverse all j via the remaining 'j' dimension and only use j>i
	// ---------------------------------------------------------------------
	traverser(x_ref, y_ref, A_ref).template for_dims<'i'>([&](auto trav_inv) {
		auto s_inv = trav_inv.state();
		const std::size_t inv = get_index<'i'>(s_inv);
		const std::size_t i_idx = n - 1 - inv;

		// Row view of A at i
		auto A_row_i = A_ref ^ noarr::fix<'i'>(i_idx);

		num_t w = y_ref[noarr::idx<'i'>(i_idx)];

		trav_inv.for_each([&](auto state) {
			const std::size_t j_idx = get_index<'j'>(state);
			if (j_idx > i_idx) {
				w -= A_row_i[noarr::idx<'j'>(j_idx)] *
				     x_ref[noarr::idx<'i'>(j_idx)];
			}
		});

		x_ref[noarr::idx<'i'>(i_idx)] =
			w / A_row_i[noarr::idx<'j'>(i_idx)];
	});
}

