	//   for (j = 0; j < i; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < j; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w / A[j][j];
	//   }
	//   for (j = i; j < N; j++) {
	//     w = A[i][j];
	//     for (k = 0; k < i; k++)
	//       w -= A[i][k] * A[k][j];
	//     A[i][j] = w;
	//   }
	// }
	//
	// We implement the same computation using Noarr traversers only.
	// For each (i, j) we compute
	//
	//   max_k = min(j, i);
	//   w = A[i][j] - sum_{k=0..max_k-1} A[i][k] * A[k][j];
	//   if (j < i) A[i][j] = w / A[j][j];    // L-part
	//   else       A[i][j] = w;              // U-part
	//
	// The inner sum is expressed as a dot product over a synthetic 'k'
	// dimension, created via renaming and slicing:
	//   - row_i_k:  row i, indexed by k (former j)
	//   - col_j_k:  column j, indexed by k (former i)
	//   - both sliced to [0, max_k)
	// ---------------------------------------------------------------------
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		// 1D view of row i: dims = 'j'
		auto row_i    = A ^ noarr::fix<'i'>(i_idx);
		// Reinterpret row as vector over synthetic dim 'k'
		auto row_i_k  = row_i ^ noarr::rename<'j', 'k'>();

		// Traverse all columns j for this fixed i
		trav_i.for_each([&](auto state) {
			std::size_t j_idx = get_index<'j'>(state);

			num_t w = A[state];

			// max_k = min(j, i)
			std::size_t max_k = (j_idx < i_idx) ? j_idx : i_idx;

			if (max_k > 0) {
				// Column view for current j: dims = 'i'
				auto col_j   = A ^ noarr::fix<'j'>(j_idx);
				// Reinterpret column as vector over synthetic dim 'k'
				auto col_j_k = col_j ^ noarr::rename<'i', 'k'>();

				// Prefix [0, max_k) of both row and column – the active part
				auto row_prefix = row_i_k ^ noarr::slice<'k'>(std::size_t(0), max_k);
				auto col_prefix = col_j_k ^ noarr::slice<'k'>(std::size_t(0), max_k);

				// Dot product over k: sum A[i][k] * A[k][j]
				num_t dot = num_t(0);
				traverser(row_prefix, col_prefix).for_each([&](auto s_k) {
					dot += row_prefix[s_k] * col_prefix[s_k];
				});

				w -= dot;
			}

			if (j_idx < i_idx) {
				// L-part: divide by diagonal A[j][j]
				auto diag_state = idx<'i', 'j'>(j_idx, j_idx);
				A[state] = w / A[diag_state];
			} else {
