	// ---------------------------------------------------------------------
	traverser(A, b, y).template for_dims<'i'>([&](auto trav_i) {
		auto s_i  = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		num_t w = b[s_i];

		if (i_idx > 0) {
			// Row i: dims 'j' -> rename to 'k'
			auto row_i = A ^ noarr::fix<'i'>(i_idx);
			auto row_k = row_i ^ noarr::rename<'j', 'k'>();

			// y: dims 'i' -> rename to 'k'
			auto y_k = y ^ noarr::rename<'i', 'k'>();

			// Prefix [0, i_idx) – L-part of row i and known entries of y
			auto row_prefix = row_k ^ noarr::slice<'k'>(std::size_t(0), i_idx);
			auto y_prefix   = y_k   ^ noarr::slice<'k'>(std::size_t(0), i_idx);

			num_t dot = num_t(0);
