	// The inner sum is a dot product between:
	//   - U-part of row i: A[i][i+1..N-1]
	//   - x[i+1..N-1]
	// ---------------------------------------------------------------------
	traverser(A, x, y).template for_dims<'i'>([&](auto trav_inv) {
		auto s_inv = trav_inv.state();
		std::size_t inv = get_index<'i'>(s_inv);
		std::size_t i_idx = n - 1 - inv;

		auto s_i = idx<'i'>(i_idx);

