	// A_rt: A[r][t]
	auto A_rt = A.get_ref() ^ noarr::rename<'i', 'r', 'j', 't'>();
	// A_st: A[s][t]
	auto A_st = A.get_ref() ^ noarr::rename<'i', 's', 'j', 't'>();
