		// Fixed i for this row
		auto s_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(s_i);

		// Iterate all columns j in this row
		trav_i.for_each([&](auto s_ij) {
			std::size_t j_idx = get_index<'j'>(s_ij);

			num_t w = A[s_ij];

			// Upper bound of the k-summation
			std::size_t max_k = (j_idx < i_idx) ? j_idx : i_idx;

			// 1D Noarr structure over k = 0..max_k-1
			// Using a scalar<char> payload as we only need indices.
			auto k_struct =
				noarr::scalar<char>() ^ noarr::vector<'k'>(max_k);

			// Accumulate the dot product using a Noarr traverser
			noarr::traverser(k_struct).for_each([&](auto s_k) {
				std::size_t k = get_index<'k'>(s_k);

				// A[i][k]
				auto s_ik = noarr::idx<'i', 'j'>(i_idx, k);
				// A[k][j]
				auto s_kj = noarr::idx<'i', 'j'>(k, j_idx);

				w -= A[s_ik] * A[s_kj];
			});

			if (j_idx < i_idx) {
				// Divide by diagonal element A[j][j] to form L(i,j)
				auto s_jj = noarr::idx<'i', 'j'>(j_idx, j_idx);
				A[s_ij] = w / A[s_jj];
